import { Heading } from '@hexa-ui/components';
import { RelatedAnalysisCard } from 'pages/components/RelatedAnalysisCard';

import { StyledContainer, StyledSection } from '../../ComponentsPage.styles';

const noop = () => {
  return null;
};

export const RelatedAnalysisCardExample = () => {
  return (
    <StyledContainer>
      <StyledSection>
        <Heading>Related Analysis Card — without warning</Heading>
      </StyledSection>

      <StyledSection>
        <RelatedAnalysisCard
          title="Connect Brand Power to business performance"
          description="Open Performance Tool with Power selected to compare brand strength with YTD performance, segment and market results."
          buttonLabel="Open Performance Tool"
          onNavigate={noop}
          dataTestId="related-analysis-card-example-no-warning"
        />
      </StyledSection>

      <StyledSection>
        <Heading>Related Analysis Card — with warning</Heading>
      </StyledSection>

      <StyledSection>
        <RelatedAnalysisCard
          title="Connect Brand Power to business performance"
          description="Open Performance Tool with Power selected to compare brand strength with YTD performance, segment and market results."
          buttonLabel="Open Performance Tool"
          onNavigate={noop}
          warning="Unsupported Performance Tool filters will not be applied"
          dataTestId="related-analysis-card-example-with-warning"
        />
      </StyledSection>
    </StyledContainer>
  );
};
